import { readFileSync } from "node:fs";
import path from "node:path";
import { METRIC_IDS, type Percentiles, type Player, type PlayerProfile } from "../shared/types.ts";

// Generated by scripts/generate-players.ts, so trusted. Swap in a real data feed here.
const PLAYERS = JSON.parse(readFileSync(path.join(process.cwd(), "data", "players.json"), "utf8")) as Player[];

/** Percentile of `value` within `sorted` (mid-rank for ties), 0-100. */
export function percentileOf(sorted: number[], value: number): number {
  const below = sorted.filter((v) => v < value).length;
  const equal = sorted.filter((v) => v === value).length;
  return Math.round(((below + equal / 2) / sorted.length) * 100);
}

/** Percentiles are against players in the same position: a CB's dribbling is compared with other CBs. */
function withPercentiles(players: Player[]): PlayerProfile[] {
  const sortedByPosition = new Map<string, Record<string, number[]>>();
  for (const p of players) {
    const table = sortedByPosition.get(p.position) ?? {};
    for (const m of METRIC_IDS) (table[m] ??= []).push(p.metrics[m]);
    sortedByPosition.set(p.position, table);
  }
  for (const table of sortedByPosition.values()) for (const values of Object.values(table)) values.sort((a, b) => a - b);

  return players.map((p) => {
    const table = sortedByPosition.get(p.position)!;
    const percentiles = Object.fromEntries(METRIC_IDS.map((m) => [m, percentileOf(table[m]!, p.metrics[m])])) as Percentiles;
    return { ...p, percentiles };
  });
}

export const PROFILES: readonly PlayerProfile[] = withPercentiles(PLAYERS);

export const getPlayer = (id: string): PlayerProfile | undefined => PROFILES.find((p) => p.id === id);

const plain = (s: string) => s.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLowerCase().trim();

/** Forgiving name lookup: exact, then contains, then surname. */
export function findByName(name: string): PlayerProfile | undefined {
  const q = plain(name);
  if (!q) return undefined;
  return (
    PROFILES.find((p) => plain(p.name) === q) ??
    PROFILES.find((p) => plain(p.name).includes(q)) ??
    PROFILES.find((p) => q.includes(plain(p.name).split(" ").at(-1)!))
  );
}
